WITH kept_keys AS (SELECT id FROM shipments EXCEPT ALL SELECT id FROM shipments WHERE delivered_date BETWEEN '2023-10-01' AND '2025-09-01'), kept_rows AS (SELECT s.* FROM shipments s JOIN kept_keys k ON s.id = k.id) SELECT DATE_TRUNC('QUARTER', shipped_date) AS quarter_start, CASE WHEN cost >= 84 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, COUNT(*) AS cnt, COUNT(*) AS row_count, SUM(cost) FILTER (WHERE status = 'RETURNED') AS returned_total_cost, COUNT(CASE WHEN carrier = 'DHL' THEN 1 END) AS dhl_count, SIZE(COLLECT_SET(status)) AS num_status, STDDEV_SAMP(cost) AS cost_stddev FROM kept_rows GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', shipped_date), CASE WHEN cost >= 84 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('QUARTER', shipped_date)))
